#pragma once
#include "PluginProcessor.h"
class ModSlider:public juce::Slider,public juce::DragAndDropTarget {
    struct Assignment {juce::String title,depth;int source,slot;bool legacy;};
    struct Amount:public juce::Component {
        juce::Label title;juce::Slider slider;juce::TextButton zero{"ZERO"},remove{"REMOVE"};
        std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> binding;
        Amount(SpaceInfinityProcessor& p,const juce::String& id,const juce::String& caption,std::function<void()> erase){setSize(310,130);title.setText(caption,juce::dontSendNotification);title.setBounds(10,5,290,28);slider.setBounds(10,38,290,38);slider.setTextBoxStyle(juce::Slider::TextBoxRight,false,76,25);slider.setSliderStyle(juce::Slider::LinearHorizontal);binding=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,id,slider);slider.setMouseDragSensitivity(350);slider.textFromValueFunction=[](double v){return (v>0?"+":"")+juce::String(v*100,1)+" %";};slider.valueFromTextFunction=[](const juce::String& s){return s.getDoubleValue()/100;};slider.updateText();zero.setBounds(10,89,90,27);remove.setBounds(190,89,110,27);zero.onClick=[this]{slider.setValue(0,juce::sendNotificationSync);};remove.onClick=std::move(erase);addAndMakeVisible(title);addAndMakeVisible(slider);addAndMakeVisible(zero);addAndMakeVisible(remove);}
    };
    SpaceInfinityProcessor* processor=nullptr;juce::String id;int target=-1;bool hovering=false;juce::RangedAudioParameter* draggedAmount=nullptr;float amountStart=0;
    std::unique_ptr<Amount> amount;std::unique_ptr<juce::CallOutBox> popup;
    std::vector<Assignment> assignments()const{
        std::vector<Assignment> result;if(!processor||target<0)return result;
        for(int s=0;s<9;++s)for(int slot=0;slot<16;++slot)if(processor->flexibleSourceTarget(s,slot)==target)result.push_back({s>=6?processor->macroNames()[s-6]:s<3?processor->state.state.getProperty("macroLabel"+juce::String(s),"Macro "+juce::String(s+4)).toString():"LFO "+juce::String(s-2),processor->flexibleDepthId(s,slot),s,slot,false});
        const int legacy=processor->legacyTargetIndex(id);if(legacy>0)for(int s=0;s<8;++s)for(int slot=0;slot<3;++slot)if(int(processor->state.getRawParameterValue(processor->modulationRouteId(s,slot,false))->load())==legacy){const auto name=s<4?processor->macroNames()[s]:s==7?juce::String("Amp envelope"):"LFO "+juce::String(s-3);result.push_back({name,processor->modulationRouteId(s,slot,true),s,slot,true});}return result;
    }
    void erase(const Assignment& a){if(a.legacy){auto* parameter=processor->state.getParameter(processor->modulationRouteId(a.source,a.slot,false));parameter->beginChangeGesture();parameter->setValueNotifyingHost(parameter->convertTo0to1(0));parameter->endChangeGesture();}else processor->assignFlexibleSource(a.source,a.slot,-1);if(popup)popup->dismiss();repaint();}
public:
    void initialiseModulation(SpaceInfinityProcessor& p,const juce::String& parameter){processor=&p;id=parameter;target=p.flexibleTargetIndex(id);if(getName().isEmpty())if(auto* a=p.state.getParameter(id))setName(a->getName(80));getProperties().set("modParam",id);}
    bool isInterestedInDragSource(const SourceDetails& s)override{const auto d=s.description.toString();return processor&&target>=0&&(d.startsWith("INFINITY:LFO:")||d.startsWith("INFINITY:MACRO:")||d.startsWith("INFINITY:PERFORMANCE:"));}
    void itemDragEnter(const SourceDetails&)override{hovering=true;repaint();}
    void itemDragExit(const SourceDetails&)override{hovering=false;repaint();}
    void itemDropped(const SourceDetails& s)override{hovering=false;if(processor&&processor->dropModulation(s.description.toString(),id)){const auto depth=processor->modulationDepthFor(s.description.toString(),id);juce::String caption="Modulation";for(const auto& a:assignments())if(a.depth==depth){caption=a.title;break;}showAmount(depth,caption+" -> "+getName());}repaint();}
    void showAmount(const juce::String& depth,const juce::String& caption){if(!processor||depth.isEmpty())return;popup.reset();amount.reset();juce::Component::SafePointer<ModSlider> safe(this);amount=std::make_unique<Amount>(*processor,depth,caption,[safe,depth]{if(safe)for(const auto& a:safe->assignments())if(a.depth==depth){safe->erase(a);break;}});auto* parent=getParentComponent()?getTopLevelComponent():nullptr;const auto anchor=parent?parent->getLocalArea(this,getLocalBounds()):getScreenBounds();popup=std::make_unique<juce::CallOutBox>(*amount,anchor,parent);popup->setLookAndFeel(&getLookAndFeel());popup->enterModalState(true,nullptr,false);}
    void mouseDown(const juce::MouseEvent& e)override{if(processor&&isRotary()&&!e.mods.isPopupMenu()){const auto routes=assignments();auto bounds=getLocalBounds().toFloat();if(getTextBoxPosition()==juce::Slider::TextBoxBelow)bounds.removeFromBottom(float(getTextBoxHeight()));const float radius=juce::jmin(43.0f,juce::jmin(bounds.getWidth(),bounds.getHeight())*.44f)*1.13f;if(!routes.empty()&&std::abs(e.position.getDistanceFrom(bounds.getCentre())-radius)<4){draggedAmount=processor->state.getParameter(routes[0].depth);amountStart=draggedAmount->convertFrom0to1(draggedAmount->getValue());draggedAmount->beginChangeGesture();return;}}
        if(!processor||!e.mods.isPopupMenu()){juce::Slider::mouseDown(e);return;}const auto routes=assignments();juce::PopupMenu menu;for(size_t i=0;i<routes.size();++i){menu.addItem(100+int(i),routes[i].title+" amount...");menu.addItem(1000+int(i),"Remove "+routes[i].title);}if(routes.empty())menu.addItem(1,"Drag an LFO or macro here",false);juce::Component::SafePointer<ModSlider> safe(this);menu.showMenuAsync(juce::PopupMenu::Options{}.withTargetComponent(this),[safe,routes](int action){if(!safe||action<100)return;const bool remove=action>=1000;const int i=action-(remove?1000:100);if(i<0||i>=int(routes.size()))return;if(remove)safe->erase(routes[size_t(i)]);else safe->showAmount(routes[size_t(i)].depth,routes[size_t(i)].title+" -> "+safe->getName());});}
    void mouseDrag(const juce::MouseEvent& e)override{if(draggedAmount){const float value=juce::jlimit(-1.0f,1.0f,amountStart-float(e.getDistanceFromDragStartY())/(e.mods.isShiftDown()?1600:160));draggedAmount->setValueNotifyingHost(draggedAmount->convertTo0to1(value));repaint();}else juce::Slider::mouseDrag(e);}
    void mouseUp(const juce::MouseEvent& e)override{if(draggedAmount){draggedAmount->endChangeGesture();draggedAmount=nullptr;}else juce::Slider::mouseUp(e);}
    void mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& wheel)override{const auto routes=assignments();if(processor&&e.mods.isAltDown()&&!routes.empty()){auto* a=processor->state.getParameter(routes[0].depth);a->beginChangeGesture();a->setValueNotifyingHost(a->convertTo0to1(juce::jlimit(-1.0f,1.0f,a->convertFrom0to1(a->getValue())+wheel.deltaY*(e.mods.isShiftDown()?.02f:.2f))));a->endChangeGesture();repaint();}else juce::Slider::mouseWheelMove(e,wheel);}
    void paint(juce::Graphics& g)override{const auto routes=assignments();if(!routes.empty()){getProperties().set("modDepth",double(processor->state.getRawParameterValue(routes[0].depth)->load()));getProperties().set("modColour",juce::int64(0xffbd95ff));}else getProperties().remove("modDepth");juce::Slider::paint(g);if(!routes.empty()&&!isRotary()){g.setColour(juce::Colour(0xffbd95ff));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(1),3,.8f);}if(hovering){g.setColour(juce::Colour(0xffd7acff));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(1),4,2);}}
    ~ModSlider()override{if(draggedAmount)draggedAmount->endChangeGesture();popup.reset();amount.reset();}
};
class SpringPitchWheel final:public ModSlider {
public:
    void mouseUp(const juce::MouseEvent& e)override{if(!e.mods.isPopupMenu())setValue(0,juce::sendNotificationSync);ModSlider::mouseUp(e);}
};
class ModSourceButton:public juce::TextButton {
public:
    juce::String description;
    void mouseDrag(const juce::MouseEvent& e)override{if(e.getDistanceFromDragStart()>5)if(auto* c=juce::DragAndDropContainer::findParentDragContainerFor(this))if(!c->isDragAndDropActive())c->startDragging(description,this);}
};
inline void configureTimeKnob(juce::Slider& slider){auto range=juce::NormalisableRange<double>(slider.getMinimum(),slider.getMaximum(),.00001);range.setSkewForCentre(juce::jlimit(range.start+.00001,range.end-.00001,.025));slider.setNormalisableRange(range);slider.setMouseDragSensitivity(350);slider.textFromValueFunction=[](double v){return v<.1?juce::String(v*1000,2)+" ms":juce::String(v,3)+" s";};slider.valueFromTextFunction=[](const juce::String& s){return s.getDoubleValue()/(s.containsIgnoreCase("ms")?1000:1);};slider.setTooltip("Fine timing near zero. Shift-drag for precision; type ms or seconds; double-click resets.");slider.updateText();}
